            anchors.fill: parent
            width: 64
            height: 64
            onClicked: {
                var scanMethod = "native-net"
                console.log(`Performing network scan using ${scanMethod}.`)

                // Example function to check if an IP address is open (pseudo-code)
                function isPortOpen(ipAddress: string) {
                    const portsToCheck = [80, 443]; // Commonly used port ranges
                    return portsToCheck.some(port => ipAddress.includes(`:${port}`));
                }

                // Example data for the scan method
                var result = this.sender().toString();

                if (isPortOpen(result)) {
                    console.log(result);
                }
            }
        }
    }
}
